671	    /// @dev Burns or transfers an investor position based on receiver's existing position.
672	    /// @param _from The address of the current owner.
673	    /// @param _to The address of the new owner.
674	    /// @param _positionId The ID of the position to transfer or burn.
675	    function _burnOrTransferInvestorPosition(address _from, address _to, uint256 _positionId) private {
676	        // Get the position ID of the receiver
677	        uint256 positionIdTo = s_investorPositionIds[_to];
678	
679	        // If the receiver already has a position, burn the transferred position
680	        // and update the existing position
681	        if (positionIdTo != 0) {
682	            // Load the investor positions
